// generate.mjs - Generates docs/generated/ from the code, never by hand
// Exposes: node scripts/generate.mjs; build() for check.mjs
//
// A list that the code holds (rules, selectors, columns, operations) is
// generated instead of copied: a hand-written copy becomes wrong at the first
// change. check.mjs fails when a generated file is out of date.
import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUT = path.join(ROOT, 'docs', 'generated');
const read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8');

function loadExtension() {
  const files = ['src/core/config.js', 'src/core/lol.js', 'src/data/selectors.js', 'src/filters/rules.js'];
  const ctx = vm.createContext({});
  ctx.globalThis = ctx;
  files.forEach((f) => vm.runInContext(read('extension/' + f), ctx, { filename: f }));
  return ctx.DuoGG;
}

const cell = (s) => String(s == null ? '' : s).replace(/\|/g, '\\|').replace(/\n/g, ' ');

function header(answers, notAnswers, source) {
  return `> **Answers**: ${answers}\n> **Does not answer**: ${notAnswers}\n\n` +
    `Generated by \`scripts/generate.mjs\` from \`${source}\`. Do not edit this file: ` +
    'change the source, then run `npm run gen`.\n\n';
}

function rules(D) {
  let md = '# Rules and sorts\n\n' + header('which filter rules exist · their default state · their threshold · which sorts exist',
    'how a rule decides → [`../filters/rules.md`](../filters/rules.md)', 'extension/src/filters/rules.js');
  md += '| Id | Label | On by default | Threshold | Hides |\n| -- | ----- | ------------- | --------- | ----- |\n';
  D.RULES.forEach((r) => {
    const p = r.param ? `\`${r.param.key}\` = ${r.param.value}` : '';
    md += `| \`${r.id}\` | ${cell(r.label)} | ${r.on ? 'yes' : 'no'} | ${p} | ${cell(r.what)} |\n`;
  });
  md += '\n## Sorts\n\n| Id | Label | Direction |\n| -- | ----- | --------- |\n';
  D.SORTS.forEach((s) => { md += `| \`${s.id}\` | ${cell(s.label)} | ${s.key ? (s.desc ? 'descending' : 'ascending') : 'site order'} |\n`; });
  return md;
}

function selectors(D) {
  let md = '# DOM selectors of the site\n\n' + header('which selector reads which data of the site',
    'repairing after a site update → [`../architecture/dom-selectors.md`](../architecture/dom-selectors.md)', 'extension/src/data/selectors.js');
  md += '| Key | Selector | Targets |\n| --- | -------- | ------- |\n';
  Object.keys(D.SELECTORS).forEach((k) => {
    const s = D.SELECTORS[k];
    md += `| \`${k}\` | \`${cell(s.css)}\`${s.text ? ` + text \`${cell(s.text)}\`` : ''} | ${cell(s.what)} |\n`;
  });
  return md;
}

function schema() {
  const sql = read('db/schema.sql');
  let md = '# Table columns\n\n' + header('which tables and columns exist · their type · their default value',
    'what a table is for, the grants → [`../database/schema.md`](../database/schema.md)', 'db/schema.sql');
  for (const m of sql.matchAll(/create table if not exists (\w+) \(([\s\S]*?)\n\);/g)) {
    md += `## ${m[1]}\n\n| Column | Type | Default |\n| ------ | ---- | ------- |\n`;
    m[2].split('\n').map((l) => l.trim().replace(/,$/, '')).filter((l) => /^[a-z_0-9]+\s/.test(l) && !/^primary key/.test(l))
      .forEach((l) => {
        const [col, ...rest] = l.split(/\s+/);
        const def = (l.match(/default (.+)$/) || [])[1] || '';
        const type = rest.join(' ').replace(/ default .*$/, '');
        md += `| \`${col}\` | ${cell(type)} | ${def ? '`' + cell(def) + '`' : ''} |\n`;
      });
    const pk = m[2].match(/primary key \(([^)]+)\)/);
    if (pk) md += `\nPrimary key: \`(${pk[1]})\`.\n`;
    md += '\n';
  }
  return md.trimEnd() + '\n';
}

function operations() {
  const model = read('extension/src/store/model.js');
  const worker = read('extension/src/store/worker.js');
  const ops = [...model.matchAll(/case '([a-z.]+)':/g)].map((m) => m[1]);
  const msgs = [...worker.matchAll(/case '([a-z.]+)':/g)].map((m) => m[1]);
  let md = '# Store messages and operations\n\n' + header('which messages the service worker accepts · which operations change the local database',
    'their effect on the sync → [`../database/sync.md`](../database/sync.md)', 'extension/src/store/worker.js and model.js');
  md += '## Messages (`chrome.runtime.sendMessage`)\n\n' + msgs.map((m) => `- \`${m}\``).join('\n') + '\n\n';
  md += '## Operations (`{ type: \'op\', op: { kind } }`)\n\n' + ops.map((o) => `- \`${o}\``).join('\n') + '\n';
  return md;
}

export function build() {
  const D = loadExtension();
  return {
    'rules.md': rules(D),
    'selectors.md': selectors(D),
    'schema.md': schema(),
    'operations.md': operations()
  };
}

if (path.resolve(process.argv[1] || '') === fileURLToPath(import.meta.url)) {
  fs.mkdirSync(OUT, { recursive: true });
  const files = build();
  Object.keys(files).forEach((f) => {
    fs.writeFileSync(path.join(OUT, f), files[f]);
    console.log('docs/generated/' + f);
  });
}
